5439	/// The path arguments of one traced file syscall, lexical, as strace printed
5440	/// them, each with whether the call can change what the path names (F-44).
5441	/// Two-path syscalls yield both strings; a symlink's target counts as written
5442	/// because a link INTO the locked corpus is the second-name attack. strace
5443	/// prints one syscall per line, so the earliest needle is the line's call.
5444	fn scope_trace_line_accesses(line: &str) -> Vec<(String, bool)> {
5445	    let Some((open, needle)) = FILE_SYSCALLS
5446	        .into_iter()
5447	        .filter_map(|needle| line.find(needle).map(|index| (index, needle)))
5448	        .min_by_key(|(index, _)| *index)
5449	    else {
5450	        return Vec::new();
5451	    };
5452	    let rest = &line[open..];
5453	    let write = WRITE_SYSCALLS.contains(&needle)
5454	        || (OPEN_SYSCALLS.contains(&needle)
5455	            && OPEN_WRITE_FLAGS.iter().any(|flag| rest.contains(flag)));
5456	    let wanted = if TWO_PATH_SYSCALLS.contains(&needle) {
5457	        2
5458	    } else {
5459	        1
5460	    };
5461	    let mut out = Vec::with_capacity(wanted);
5462	    let mut cursor = rest;
5463	    for _ in 0..wanted {
5464	        let Some(start) = cursor.find('"') else { break };
5465	        let Some(end) = cursor[start + 1..].find('"') else {
5466	            break;
5467	        };
5468	        out.push((cursor[start + 1..start + 1 + end].to_owned(), write));
5469	        cursor = &cursor[start + 1 + end + 1..];
5470	    }
5471	    out
5472	}
