5521	/// `chdir("x") = 0` moves this pid; a failed chdir moves nothing, and a
5522	/// relative target moves it relative to where it already stood (A07).
5523	/// Give a line's relative paths the directory they were actually opened
5524	/// against: a directory fd if the call names one, else the pid's cwd (A07,
5525	/// A12). An absolute path is already anchored.
5526	fn anchor_relative_paths(
5527	    line: &str,
5528	    pid: u32,
5529	    dir_fds: &BTreeMap<(u32, i64), String>,
5530	    cwds: &BTreeMap<u32, String>,
5531	    accesses: &mut [(String, bool)],
5532	) {
5533	    let dirfd = line
5534	        .split_once("openat(")
5535	        .or_else(|| line.split_once("openat2("))
5536	        .and_then(|(_, rest)| rest.split(',').next())
5537	        .and_then(|token| token.trim().parse::<i64>().ok());
5538	    let base = dirfd
5539	        .and_then(|fd| dir_fds.get(&(pid, fd)))
5540	        .or_else(|| cwds.get(&pid));
5541	    let Some(base) = base else {
5542	        return;
5543	    };
5544	    for (path, _) in accesses.iter_mut() {
5545	        if !path.starts_with('/') {
5546	            *path = format!("{base}/{path}");
5547	        }
5548	    }
5549	}
