5551	fn record_chdir(line: &str, pid: u32, cwds: &mut BTreeMap<u32, String>) {
5552	    // `fchdir(fd)` names no path; its argument would become a nonsense cwd.
5553	    if !line.contains("chdir(") || line.contains("fchdir(") || !line.trim_end().ends_with("= 0") {
5554	        return;
5555	    }
5556	    let Some((target, _)) = scope_trace_line_accesses(line).first().cloned() else {
5557	        return;
5558	    };
5559	    let resolved = if target.starts_with('/') {
5560	        target
5561	    } else {
5562	        cwds.get(&pid)
5563	            .map_or_else(|| target.clone(), |cwd| format!("{cwd}/{target}"))
5564	    };
5565	    cwds.insert(pid, resolved);
5566	}
