9371	/// Scan the implementation crates' non-test sources for concurrency
9372	/// primitives. A file's trailing `#[cfg(test)]` module is skipped; comment
9373	/// lines are skipped. Deterministic order: crates, files and lines sorted.
9374	fn scan_concurrency_primitives(root: &Utf8Path) -> Result<ConcurrencyScan> {
9375	    fn walk(dir: &Utf8Path, out: &mut Vec<Utf8PathBuf>) -> Result<()> {
9376	        let mut entries = fs::read_dir(dir.as_std_path())
9377	            .with_context(|| format!("read {dir}"))?
9378	            .map(|entry| entry.map(|e| e.path()))
9379	            .collect::<std::io::Result<Vec<_>>>()?;
9380	        entries.sort();
9381	        for path in entries {
9382	            let path = Utf8PathBuf::from_path_buf(path)
9383	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
9384	            if path.is_dir() {
9385	                walk(&path, out)?;
9386	            } else if path.extension() == Some("rs") {
9387	                out.push(path);
9388	            }
9389	        }
9390	        Ok(())
9391	    }
9392	    let mut scan = ConcurrencyScan {
9393	        execution: Vec::new(),
9394	        sync: Vec::new(),
9395	    };
9396	    let crates_dir = root.join("crates");
9397	    let mut crate_dirs = fs::read_dir(crates_dir.as_std_path())
9398	        .with_context(|| format!("read {crates_dir}"))?
9399	        .map(|entry| entry.map(|e| e.path()))
9400	        .collect::<std::io::Result<Vec<_>>>()?;
9401	    crate_dirs.sort();
9402	    for member in crate_dirs {
9403	        let member_dir = Utf8PathBuf::from_path_buf(member)
9404	            .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
9405	        let Some(name) = member_dir.file_name() else {
9406	            continue;
9407	        };
9408	        if CONCURRENCY_SCAN_EXCLUDED_CRATES.contains(&name) || !member_dir.join("src").is_dir() {
9409	            continue;
9410	        }
9411	        let mut files = Vec::new();
9412	        walk(&member_dir.join("src"), &mut files)?;
9413	        for file in files {
9414	            let text = fs::read_to_string(&file).with_context(|| format!("read {file}"))?;
9415	            let relative = file.strip_prefix(root).unwrap_or(&file);
9416	            // Blind pass 1 at 612cbcc (A06): this used to stop at the first
9417	            // `#[cfg(test)]` line, so production code after an earlier test
9418	            // module escaped the scan. The attributed item is skipped as a
9419	            // block (brace depth) or, for a brace-less item, through its `;`,
9420	            // and scanning resumes after it. Braces are counted textually,
9421	            // strings and comments included: an unbalanced brace inside a
9422	            // test module's string literal could end the skip early (a
9423	            // spurious refusal, the safe direction) or late (a missed
9424	            // production spawn) — the module's own code is scanned, not
9425	            // reasoned about, and a lane refusal is the visible outcome.
9426	            let mut skipping: Option<(usize, bool)> = None;
9427	            for (index, line) in text.lines().enumerate() {
9428	                let trimmed = line.trim();
9429	                if let Some((depth, entered)) = skipping.as_mut() {
9430	                    *depth += line.matches('{').count();
9431	                    let closes = line.matches('}').count();
9432	                    if *depth > 0 {
9433	                        *entered = true;
9434	                    }
9435	                    *depth = depth.saturating_sub(closes);
9436	                    if (*entered && *depth == 0) || (!*entered && trimmed.ends_with(';')) {
9437	                        skipping = None;
9438	                    }
9439	                    continue;
9440	                }
9441	                if trimmed == "#[cfg(test)]" {
9442	                    skipping = Some((0, false));
9443	                    continue;
9444	                }
9445	                if trimmed.starts_with("//") {
9446	                    continue;
9447	                }
9448	                for token in CONCURRENCY_EXECUTION_PRIMITIVES {
9449	                    if line.contains(token) {
9450	                        scan.execution
9451	                            .push(format!("{relative}:{}:{token}", index + 1));
9452	                    }
9453	                }
9454	                for token in CONCURRENCY_SYNC_PRIMITIVES {
9455	                    if line.contains(token) {
9456	                        scan.sync.push(format!("{relative}:{}:{token}", index + 1));
9457	                    }
9458	                }
9459	            }
9460	        }
9461	    }
9462	    Ok(scan)
9463	}
