5574	    // the permitted read; the write carried no fragment. Directory fds are
5575	    // remembered per pid from their open's return value, and a path relative
5576	    // to one is judged under that directory. An `<unfinished ...>` open is
5577	    // completed by its `<... openat resumed>) = fd` line.
5578	    let mut dir_fds: BTreeMap<(u32, i64), String> = BTreeMap::new();
5579	    let mut unfinished: BTreeMap<u32, (String, bool)> = BTreeMap::new();
5580	    // Blind pass 1 at aa00d41 (A07): a `chdir` into the locked corpus made
5581	    // every later relative write nameless — no fragment, and resolution
5582	    // against the repository root put it somewhere harmless. The cwd each pid
5583	    // announces is remembered, and its relative paths resolve there.
5584	    let mut cwds: BTreeMap<u32, String> = BTreeMap::new();
5585	    loop {
5586	        buf.clear();
5587	        if reader.read_until(b'\n', &mut buf)? == 0 {
