1042	/// Independent source/CST oracle. It compares raw observed bytes, not parser
1043	/// equality or a formatter-owned snapshot.
1044	fn independent_oracle_source_cst(
1045	    source: &str,
1046	    emitted: &str,
1047	    once: &str,
1048	    twice: &str,
1049	) -> Result<Vec<u8>> {
1050	    anyhow::ensure!(emitted == source, "CST emit is not lossless for {source:?}");
1051	    anyhow::ensure!(once == twice, "formatting is not idempotent");
1052	    let mut witness = emitted.as_bytes().to_vec();
1053	    witness.extend_from_slice(once.as_bytes());
1054	    Ok(witness)
1055	}
