1066	    let liminal_source::merge::MergeOutcome::Disjoint { merged } = identity else {
1067	        anyhow::bail!("identity merge reported non-disjoint outcome: {identity:?}");
1068	    };
1069	    let merged_tokens = merged.split_whitespace().collect::<Vec<_>>();
1070	    let ours_tokens = ours.split_whitespace().collect::<Vec<_>>();
1071	    let mut merged_multiset = merged_tokens.clone();
1072	    let mut ours_multiset = ours_tokens.clone();
1073	    merged_multiset.sort_unstable();
1074	    ours_multiset.sort_unstable();
1075	    anyhow::ensure!(
1076	        ours_multiset == merged_multiset,
1077	        "identity merge dropped content: {ours:?} -> {merged:?}"
1078	    );
1079	    // Token multisets alone permit an implementation to drop or duplicate
1080	    // durable markers. The merge contract keeps base slot order as its primary
1081	    // layout; a pure move is therefore intentionally not an order-preserving
1082	    // relation, but its marker set must still survive exactly.
1083	    let marker_order = |text: &str| {
1084	        text.split_whitespace()
1085	            .filter(|token| token.starts_with("{#") && token.ends_with('}'))
1086	            .map(str::to_owned)
1087	            .collect::<Vec<_>>()
1088	    };
1089	    let base_markers = marker_order(base);
1090	    let ours_markers = marker_order(ours);
1091	    if ours_markers != base_markers {
1092	        let mut expected = ours_markers.clone();
1093	        let mut actual = marker_order(merged);
1094	        expected.sort_unstable();
1095	        actual.sort_unstable();
1096	        anyhow::ensure!(
1097	            actual == expected,
1098	            "identity merge changed durable marker set under layout normalization"
1099	        );
1100	        // Blind pass 1 at 612cbcc (A02): the marker SET surviving a move said
1101	        // nothing about which content each marker kept; swapping the contents
1102	        // of two moved markers passed. A move keeps every marker's content.
