1104	            ordered_block_contents(text)
1105	                .into_iter()
1106	                .filter(|(marker, _)| marker.starts_with("{#"))
1107	                .collect::<BTreeMap<_, _>>()
1108	        };
1109	        anyhow::ensure!(
1110	            markered(merged) == markered(ours),
1111	            "identity merge re-associated content across moved markers: {ours:?} -> {merged:?}"
1112	        );
