1137	fn ordered_block_contents(text: &str) -> BTreeMap<String, Vec<String>> {
1138	    let mut anonymous = 0usize;
1139	    let mut blocks = BTreeMap::new();
1140	    for block in text.split("\n\n") {
1141	        let marker = block
1142	            .split_whitespace()
1143	            .find(|token| token.starts_with("{#") && token.ends_with('}'))
1144	            .map_or_else(
1145	                || {
1146	                    let key = format!("anon:{anonymous}");
1147	                    anonymous += 1;
1148	                    key
1149	                },
1150	                str::to_owned,
1151	            );
1152	        let tokens = block
1153	            .split_whitespace()
1154	            .filter(|token| !token.starts_with("{#") || !token.ends_with('}'))
1155	            .map(str::to_owned)
1156	            .collect::<Vec<_>>();
1157	        // Blocks containing only marker tokens carry no ordinary content whose
1158	        // order can falsify this ordering oracle; marker order is checked above.
1159	        if !tokens.is_empty() {
1160	            blocks.insert(marker, tokens);
1161	        }
1162	    }
1163	    blocks
1164	}
