 30	///   → `id = None`, text unchanged.
 31	pub fn parse(input: &str) -> Vec<Block> {
 32	    let mut blocks = Vec::new();
 33	    let lines: Vec<(usize, &str)> = input.lines().enumerate().collect();
 34	
 35	    let mut block_start_line: Option<usize> = None;
 36	    let mut block_lines: Vec<(usize, &str)> = Vec::new();
 37	
 38	    for (i, line) in &lines {
 39	        let is_blank = line.trim().is_empty();
 40	
 41	        if is_blank {
 42	            if let Some(start) = block_start_line {
 43	                // End of block.
 44	                let block = build_block(input, start, &block_lines);
 45	                blocks.push(block);
 46	                block_start_line = None;
 47	                block_lines.clear();
 48	            }
 49	        } else {
 50	            if block_start_line.is_none() {
 51	                block_start_line = Some(*i);
 52	            }
 53	            block_lines.push((*i, line));
 54	        }
 55	    }
 56	
 57	    // Trailing block (no trailing blank line).
 58	    if let Some(start) = block_start_line {
 59	        let block = build_block(input, start, &block_lines);
 60	        blocks.push(block);
 61	    }
 62	
 63	    blocks
 64	}
