 66	/// Build one Block from collected lines.
 67	fn build_block(input: &str, start_line: usize, lines: &[(usize, &str)]) -> Block {
 68	    assert!(!lines.is_empty(), "block must have at least one line");
 69	
 70	    // Try to extract an ID marker from the last line.
 71	    let last_line = lines.last().unwrap().1;
 72	    let (id, last_line_cleaned) = extract_marker(last_line);
 73	
 74	    // Build text: all lines joined by \n, with the last line cleaned.
 75	    let mut text_lines: Vec<&str> = lines.iter().map(|(_, l)| *l).collect();
 76	    if id.is_some() {
 77	        // Replace last line with cleaned version.
 78	        let last_idx = text_lines.len() - 1;
 79	        let cleaned = last_line_cleaned.as_deref().unwrap_or(last_line);
 80	        if cleaned.is_empty() {
 81	            text_lines.pop();
 82	        } else {
 83	            text_lines[last_idx] = cleaned;
 84	        }
 85	    }
 86	    let text = text_lines.join("\n");
 87	
 88	    // Compute byte range. The range includes the original marker bytes and
 89	    // excludes surrounding blank lines.
 90	    let first_line_start = input
 91	        .lines()
 92	        .nth(start_line)
 93	        .map_or(0, |_| byte_offset(input, start_line));
 94	    let last_line_end = lines
 95	        .last()
 96	        .and_then(|(i, _)| {
 97	            let line_start = byte_offset(input, *i);
 98	            input.lines().nth(*i).map(|l| line_start + l.len())
 99	        })
100	        .unwrap_or(input.len());
101	
102	    Block {
103	        text,
104	        id,
105	        range: SourceRange {
106	            start: first_line_start as u64,
107	            end: last_line_end as u64,
108	        },
109	    }
110	}
111	
112	/// Extract an ID marker from the last line of a block.
113	///
114	/// Returns `(Some(id), Some(cleaned_line))` if the marker is well-formed,
115	/// `(None, None)` if malformed (text unchanged).
116	fn extract_marker(line: &str) -> (Option<String>, Option<String>) {
117	    // Find the last `{#` in the line.
118	    let Some(marker_start) = line.rfind("{#") else {
119	        return (None, None);
120	    };
121	
122	    // The marker must end with `}`.
123	    let after_hash = &line[marker_start + 2..];
124	    let Some(close) = after_hash.find('}') else {
125	        return (None, None); // unclosed
126	    };
127	
128	    let id_str = &after_hash[..close];
129	
130	    // ID must be nonempty and match `[A-Za-z0-9_-]+`.

